diff --git a/libheif/color-conversion/yuv2rgb.cc b/libheif/color-conversion/yuv2rgb.cc
index 3772ac3..cd75070 100644
--- a/libheif/color-conversion/yuv2rgb.cc
+++ b/libheif/color-conversion/yuv2rgb.cc
@@ -579,8 +579,9 @@ Op_YCbCr420_to_RRGGBBaa::state_after_conversion(const ColorState& input_state,
     return {};
   }

-  // All planes, alpha included, are read as uint16_t samples.
-  if (!input_state.all_channels_have_bytes_per_sample(2)) {
+  // All planes, alpha included, are read as uint16_t samples; a wider component
+  // ('unci' can carry up to 128 bits) does not fit.
+  if (input_state.get_max_bytes_per_sample() > 2) {
     return {};
   }

diff --git a/libheif/color-conversion/yuv2rgb.cc b/libheif/color-conversion/yuv2rgb.cc
index 0073527..42cfb55 100644
--- a/libheif/color-conversion/yuv2rgb.cc
+++ b/libheif/color-conversion/yuv2rgb.cc
@@ -580,11 +580,12 @@ Op_YCbCr420_to_RRGGBBaa::state_after_conversion(const ColorState& input_state,
     }
   }

-  // The conversion derives its shifts from one bit depth, so the three planes must share
-  // it (get_uniform_color_bits_per_pixel() is 0 when they differ) and it must be > 8.
+  // The operator converts to a 16-bit output, so it needs a source deeper than 8 bits;
+  // take the depth from the widest colour plane (get_max_color_bits_per_pixel() is 0
+  // when there are no colour planes).
   if (input_state.colorspace != heif_colorspace_YCbCr ||
       input_state.chroma != heif_chroma_420 ||
-      input_state.get_uniform_color_bits_per_pixel() <= 8) {
+      input_state.get_max_color_bits_per_pixel() <= 8) {
     return {};
   }

